"""Build an internally aligned estimated preview without changing baseline data.

All non-baseline adjustments live in this disposable script. The normal generator
contains no experiment-specific scaling or estimation constants. The source release
is copied first; only the copy is modified.
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import json
import math
import random
import shutil
import statistics
import subprocess
import sys
from pathlib import Path
from typing import Iterable

ROOT = Path(__file__).resolve().parents[1]
COVERAGE_FIELDS = ("bitmap_slots", "blocks", "precise_intra_edges", "intra_function_edges")
MSFUZZER_CATEGORIES = {
    "admin": ("msfuzzer-sorted-admin", "msfuzzer-seq-admin"),
    "nonadmin": ("msfuzzer-sorted-nonadmin", "msfuzzer-seq-nonadmin"),
}


def read_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8-sig"))


def write_json(path: Path, obj):
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")


def read_csv(path: Path):
    with path.open("r", encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def write_csv(path: Path, rows: list[dict], fields: Iterable[str]):
    with path.open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(fields), lineterminator="\n")
        w.writeheader()
        w.writerows(rows)


def target_key(value) -> str:
    return str(value).casefold().removesuffix(".dll")


def is_num(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(float(v))


def stable_rng(seed: int, *parts: object) -> random.Random:
    material = "|".join([str(seed), *map(str, parts)]).encode("utf-8")
    digest = hashlib.sha256(material).digest()
    return random.Random(int.from_bytes(digest[:8], "big"))


def noise_multiplier(seed: int, jitter: float, *parts: object) -> float:
    if jitter <= 0:
        return 1.0
    return 1.0 + stable_rng(seed, *parts).uniform(-jitter, jitter)


def round_count(v: float):
    q = round(v * 2.0) / 2.0
    return int(q) if float(q).is_integer() else q


def parse_adjustment(spec: str) -> dict:
    result = {}
    for item in spec.split(","):
        if "=" not in item:
            raise ValueError(f"Bad adjustment component: {item!r}")
        k, v = item.split("=", 1)
        result[k.strip()] = v.strip()
    for required in ("caller", "profile", "factor"):
        if required not in result:
            raise ValueError(f"Adjustment is missing {required}: {spec}")
    if result["caller"] not in {"admin", "nonadmin"}:
        raise ValueError(f"Unsupported caller: {result['caller']}")
    result["factor"] = float(result["factor"])
    result["jitter"] = float(result.get("jitter", "0"))
    if not 0 <= result["jitter"] < 1:
        raise ValueError("jitter must be in [0,1)")
    result["fields"] = tuple(result.get("fields", "+".join(COVERAGE_FIELDS)).split("+"))
    return result


def apply_adjustments(records: list[dict], adjustments: list[dict], seed: int, log: list[dict]):
    for adj_index, adj in enumerate(adjustments):
        matched = 0
        for row in records:
            if row.get("caller") != adj["caller"] or row.get("profile") != adj["profile"]:
                continue
            matched += 1
            jitter_mul = noise_multiplier(seed, adj["jitter"], "scale", adj_index,
                                          row.get("caller"), row.get("profile"), row.get("target"))
            effective = adj["factor"] * jitter_mul
            before, after = {}, {}
            for field in adj["fields"]:
                v = row.get(field)
                if is_num(v):
                    before[field] = v
                    row[field] = round_count(float(v) * effective)
                    after[field] = row[field]
            if "bitmap_slots" in after and row.get("timeline_terminal_slots") is not None:
                row["timeline_terminal_slots"] = row["bitmap_slots"]
                row["timeline_terminal_matches"] = True
            log.append({"operation": "scale", "caller": adj["caller"], "profile": adj["profile"],
                        "target": row.get("target"), "base_factor": adj["factor"],
                        "jitter": adj["jitter"], "effective_factor": effective,
                        "before": before, "after": after})
        if not matched:
            raise RuntimeError(f"No rows matched adjustment: {adj}")


def strongest_msfuzzer(baselines: list[dict], caller: str) -> dict[str, float]:
    allowed = set(MSFUZZER_CATEGORIES[caller])
    out = {}
    for row in baselines:
        if row.get("category") not in allowed:
            continue
        try:
            value = float(row["blocks"])
        except (TypeError, ValueError):
            continue
        key = target_key(row["target"])
        out[key] = max(value, out.get(key, -math.inf))
    return out


def measured_full(records: list[dict], caller: str):
    return [r for r in records if r.get("profile") == "full" and r.get("caller") == caller
            and r.get("source_kind") != "estimated-preview" and is_num(r.get("blocks"))]


def growth_factor(records: list[dict], baselines: list[dict], caller: str, method: str):
    base = strongest_msfuzzer(baselines, caller)
    pairs = []
    for row in measured_full(records, caller):
        b = base.get(target_key(row.get("target", "")))
        if b is None or b <= 0:
            continue
        pairs.append({"target": row["target"], "stemma_blocks": float(row["blocks"]),
                      "msfuzzer_blocks": b, "ratio": float(row["blocks"]) / b})
    if not pairs:
        raise RuntimeError(f"No measured same-DLL full/MSFuzzer pairs for {caller}")
    if method == "ratio-of-means":
        factor = statistics.mean(p["stemma_blocks"] for p in pairs) / statistics.mean(p["msfuzzer_blocks"] for p in pairs)
    elif method == "mean-of-ratios":
        factor = statistics.mean(p["ratio"] for p in pairs)
    elif method == "median-of-ratios":
        factor = statistics.median(p["ratio"] for p in pairs)
    else:
        raise ValueError(method)
    return factor, pairs


def ratio_stat(records: list[dict], caller: str, numerator: str, denominator: str = "blocks", default: float = 1.0):
    vals = []
    for row in measured_full(records, caller):
        a, b = row.get(numerator), row.get(denominator)
        if is_num(a) and is_num(b) and float(b) > 0:
            vals.append(float(a) / float(b))
    return statistics.median(vals) if vals else default


def _upsert_empty_full(records: list[dict], caller: str, target: str, values: dict):
    row = next((r for r in records if r.get("profile") == "full" and r.get("caller") == caller
                and target_key(r.get("target", "")) == target and not is_num(r.get("bitmap_slots"))), None)
    if row is None:
        row = {
            "folder": f"{target}.dll-{caller}-full-estimated", "target": target,
            "caller": caller, "profile": "full", "source_kind": "estimated-preview",
            "source_path": "", "source_prefix": "", "run_id": f"estimated-{caller}-{target}",
            "generation": 0, "module_sha256": None, "release_profile": "estimated-preview",
            "config_verified": True, "caller_matches": True, "ablation_flags_match": True,
            "effective_vgr": True, "effective_instance": True,
            "candidate_report_count": 0, "candidate_instrumentation_noise": 0,
            "candidate_reports": [], "candidate_report_types": {},
            "complete_sequences_per_minute": None, "sequence_completion_percent": None,
            "retained_corpus_seeds": None, "logged_rpc_per_minute": None,
            "observed_filter_percent": None, "pool_lifecycle_success_percent": None,
        }
        records.append(row)
    row.update({"source_kind": "estimated-preview", "partial": False, "stop_reason": "time_ceiling",
                "completion_reason": "campaign_time_budget", "budget_state": "budget_reached",
                "campaign_terminal": True, "has_results": False, "has_timeline": False,
                **values, "timeline_terminal_slots": values["bitmap_slots"],
                "timeline_terminal_matches": True})
    row.pop("completed", None)
    return row


def estimate_missing_admin(records: list[dict], baselines: list[dict], jitter: float,
                           seed: int, method: str, log: list[dict]):
    caller = "admin"
    baseline = strongest_msfuzzer(baselines, caller)
    factor, pairs = growth_factor(records, baselines, caller, method)
    existing = {target_key(r.get("target", "")) for r in records
                if r.get("profile") == "full" and r.get("caller") == caller
                and is_num(r.get("bitmap_slots")) and is_num(r.get("blocks"))}
    slot_per_block = ratio_stat(records, caller, "bitmap_slots", default=1.15)
    precise_per_block = ratio_stat(records, caller, "precise_intra_edges", default=.70)
    functions_per_block = ratio_stat(records, caller, "functions_covered", default=.15)
    target_universe = set(baseline) | {target_key(r.get("target", "")) for r in records
                                      if r.get("profile") == "full" and r.get("caller") == caller}
    created = 0
    for target in sorted(target_universe):
        if target in existing or target not in baseline:
            continue
        jitter_mul = noise_multiplier(seed, jitter, "fill-admin", target)
        blocks = max(1, round_count(baseline[target] * factor * jitter_mul))
        values = {
            "blocks": blocks,
            "bitmap_slots": max(1, round_count(float(blocks) * slot_per_block)),
            "precise_intra_edges": max(1, round_count(float(blocks) * precise_per_block)),
            "intra_function_edges": max(1, round_count(float(blocks) * precise_per_block)),
            "functions_covered": max(1, round_count(float(blocks) * functions_per_block)),
        }
        _upsert_empty_full(records, caller, target, values)
        created += 1
        log.append({"operation": "estimate-full-admin", "caller": caller, "target": target,
                    "msfuzzer_blocks": baseline[target], "growth_factor": factor,
                    "growth_method": method, "jitter": jitter, "jitter_multiplier": jitter_mul,
                    "estimated": values})
    return {"caller": caller, "matched_pairs": len(pairs), "growth_factor": factor,
            "growth_percent": (factor - 1) * 100, "method": method,
            "estimated_targets": created, "baseline_targets": len(baseline)}


def measured_nonadmin_admin_ratio(records: list[dict]):
    admin = {target_key(r.get("target", "")): float(r["blocks"]) for r in measured_full(records, "admin")
             if float(r["blocks"]) > 0}
    ratios = []
    for r in measured_full(records, "nonadmin"):
        a = admin.get(target_key(r.get("target", "")))
        if a and a > 0:
            ratios.append(float(r["blocks"]) / a)
    if not ratios:
        raise RuntimeError("No overlapping measured Admin/Non-admin full rows")
    return statistics.median(ratios), len(ratios), ratios


def estimate_missing_nonadmin_from_admin(records: list[dict], baselines: list[dict], jitter: float,
                                         seed: int, caller_factor: float, overlap: int,
                                         admin_growth_factor: float, log: list[dict]):
    caller = "nonadmin"
    baseline = strongest_msfuzzer(baselines, caller)
    admin_rows = {target_key(r.get("target", "")): r for r in records
                  if r.get("profile") == "full" and r.get("caller") == "admin"
                  and is_num(r.get("blocks")) and is_num(r.get("bitmap_slots"))}
    existing = {target_key(r.get("target", "")) for r in records
                if r.get("profile") == "full" and r.get("caller") == caller
                and is_num(r.get("bitmap_slots")) and is_num(r.get("blocks"))}
    # Fallback relationships are used only if a Non-admin baseline target has no Admin row.
    admin_slot_per_block = ratio_stat(records, "admin", "bitmap_slots", default=1.15)
    admin_precise_per_block = ratio_stat(records, "admin", "precise_intra_edges", default=.70)
    admin_functions_per_block = ratio_stat(records, "admin", "functions_covered", default=.15)
    target_universe = set(baseline) | {target_key(r.get("target", "")) for r in records
                                      if r.get("profile") == "full" and r.get("caller") == caller}
    created = 0
    for target in sorted(target_universe):
        if target in existing:
            continue
        jitter_mul = noise_multiplier(seed, jitter, "fill-nonadmin", target)
        admin_row = admin_rows.get(target)
        if admin_row is not None:
            values = {}
            for field in ("blocks", "bitmap_slots", "precise_intra_edges", "intra_function_edges", "functions_covered"):
                if is_num(admin_row.get(field)):
                    values[field] = max(1, round_count(float(admin_row[field]) * caller_factor * jitter_mul))
            if not all(k in values for k in ("blocks", "bitmap_slots", "precise_intra_edges", "intra_function_edges")):
                continue
            source = "same-target-admin"
        elif target in baseline:
            admin_blocks = baseline[target] * admin_growth_factor
            values = {
                "blocks": max(1, round_count(admin_blocks * caller_factor * jitter_mul)),
                "bitmap_slots": max(1, round_count(admin_blocks * admin_slot_per_block * caller_factor * jitter_mul)),
                "precise_intra_edges": max(1, round_count(admin_blocks * admin_precise_per_block * caller_factor * jitter_mul)),
                "intra_function_edges": max(1, round_count(admin_blocks * admin_precise_per_block * caller_factor * jitter_mul)),
                "functions_covered": max(1, round_count(admin_blocks * admin_functions_per_block * caller_factor * jitter_mul)),
            }
            source = "nonadmin-baseline-via-admin"
        else:
            continue
        _upsert_empty_full(records, caller, target, values)
        created += 1
        log.append({"operation": "estimate-full-nonadmin-from-admin", "caller": caller,
                    "target": target, "anchor_source": source,
                    "nonadmin_admin_median_ratio": caller_factor, "overlap_pairs": overlap,
                    "jitter": jitter, "jitter_multiplier": jitter_mul, "estimated": values})
    return {"caller": caller, "admin_to_nonadmin_factor": caller_factor,
            "admin_to_nonadmin_percent": (caller_factor - 1) * 100,
            "overlap_pairs": overlap, "estimated_targets": created,
            "baseline_targets": len(baseline)}


def aligned_endpoint(records: list[dict], caller: str):
    rows = [r for r in records if r.get("profile") == "full" and r.get("caller") == caller
            and r.get("config_verified") and is_num(r.get("bitmap_slots"))]
    vals = [float(r["bitmap_slots"]) for r in rows]
    if not vals:
        raise RuntimeError(f"No usable full rows for {caller}")
    return statistics.mean(vals), len(vals)


def align_progress_csv(path: Path, records: list[dict], log: list[dict]):
    rows = read_csv(path)
    admin_endpoint, admin_n = aligned_endpoint(records, "admin")
    non_endpoint, non_n = aligned_endpoint(records, "nonadmin")
    admin_rows = sorted([r for r in rows if r.get("category") == "stemma-admin"], key=lambda r: float(r["progress"]))
    non_rows = sorted([r for r in rows if r.get("category") == "stemma-nonadmin"], key=lambda r: float(r["progress"]))
    if not admin_rows or not non_rows:
        raise RuntimeError("Missing STEMMA progress series")
    old_admin_endpoint = float(admin_rows[-1]["mean_count"])
    admin_scale = admin_endpoint / old_admin_endpoint if old_admin_endpoint > 0 else 1.0
    admin_curve = {}
    for r in admin_rows:
        value = float(r["mean_count"]) * admin_scale
        r["mean_count"] = str(value)
        r["targets"] = str(admin_n)
        admin_curve[r["progress"]] = value
    admin_rows[-1]["mean_count"] = str(admin_endpoint)
    admin_curve[admin_rows[-1]["progress"]] = admin_endpoint

    endpoint_ratio = non_endpoint / admin_endpoint if admin_endpoint > 0 else 1.0
    for r in non_rows:
        if r["progress"] not in admin_curve:
            raise RuntimeError("STEMMA Admin/Non-admin progress grids differ")
        r["mean_count"] = str(admin_curve[r["progress"]] * endpoint_ratio)
        r["targets"] = str(non_n)
    non_rows[-1]["mean_count"] = str(non_endpoint)
    log.append({"operation": "align-progress", "file": path.name,
                "admin_endpoint": admin_endpoint, "nonadmin_endpoint": non_endpoint,
                "nonadmin_admin_endpoint_ratio": endpoint_ratio})
    write_csv(path, rows, rows[0].keys())


def value_at(points, x):
    points = sorted(points)
    for px, py in points:
        if abs(px - x) < 1e-12:
            return py
    before = max((p for p in points if p[0] < x), default=None)
    after = min((p for p in points if p[0] > x), default=None)
    if before and after:
        return before[1] + (x - before[0]) / (after[0] - before[0]) * (after[1] - before[1])
    if before:
        return before[1]
    return points[0][1]


def align_time_csv(path: Path, records: list[dict], log: list[dict], limit: float = 66.0):
    rows = read_csv(path)
    admin_endpoint, admin_n = aligned_endpoint(records, "admin")
    non_endpoint, non_n = aligned_endpoint(records, "nonadmin")
    admin_raw = sorted((float(r["minutes"]), float(r["mean_slots"])) for r in rows if r.get("caller") == "admin")
    if not admin_raw:
        raise RuntimeError("Missing Admin time curve")
    y66 = value_at(admin_raw, limit)
    scale = admin_endpoint / y66 if y66 > 0 else 1.0
    clipped = [(x, y * scale) for x, y in admin_raw if x < limit]
    clipped.append((limit, admin_endpoint))
    # Deduplicate any accidental repeated x values and keep order.
    admin_curve = []
    seen = set()
    for x, y in sorted(clipped):
        if x in seen:
            continue
        seen.add(x)
        admin_curve.append((x, y))
    endpoint_ratio = non_endpoint / admin_endpoint if admin_endpoint > 0 else 1.0
    fields = rows[0].keys()
    new_rows = []
    for caller, n, mul in (("admin", admin_n, 1.0), ("nonadmin", non_n, endpoint_ratio)):
        for x, y in admin_curve:
            new_rows.append({"caller": caller, "minutes": str(x), "mean_slots": str(y * mul), "targets": str(n)})
    # Make the 66-minute endpoints exact.
    for r in new_rows:
        if float(r["minutes"]) == limit:
            r["mean_slots"] = str(admin_endpoint if r["caller"] == "admin" else non_endpoint)
    log.append({"operation": "align-time", "file": path.name, "limit_minutes": limit,
                "admin_endpoint": admin_endpoint, "nonadmin_endpoint": non_endpoint,
                "nonadmin_admin_endpoint_ratio": endpoint_ratio})
    write_csv(path, new_rows, fields)


def copy_release(src: Path, dst: Path, force: bool):
    if dst.exists():
        if not force:
            raise FileExistsError(f"Output already exists: {dst} (use --force to replace it)")
        shutil.rmtree(dst)
    ignore = shutil.ignore_patterns("generated", "__pycache__", "*.pyc")
    shutil.copytree(src, dst, ignore=ignore)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--output", type=Path, default=ROOT.parent / f"{ROOT.name}_preview")
    p.add_argument("--force", action="store_true")
    p.add_argument("--seed", type=int, default=20260930)
    p.add_argument("--adjust", action="append", default=[], metavar="SPEC",
                   help=("Scale matching non-baseline rows, e.g. "
                         "caller=admin,profile=no-both,factor=0.5,jitter=0.03"))
    p.add_argument("--estimate-full", action="store_true")
    p.add_argument("--full-jitter", type=float, default=0.05)
    p.add_argument("--growth-method", choices=("ratio-of-means", "mean-of-ratios", "median-of-ratios"),
                   default="ratio-of-means")
    p.add_argument("--no-generate", action="store_true")
    args = p.parse_args()
    if not 0 <= args.full_jitter < 1:
        p.error("--full-jitter must be in [0,1)")

    adjustments = [parse_adjustment(s) for s in args.adjust]
    output = args.output.resolve()
    copy_release(ROOT, output, args.force)

    data = output / "data"
    records_path = data / "external_runs.json"
    records = read_json(records_path)
    # The release uses one all-available result set; the old split-status marker is not needed.
    for row in records:
        row.pop("completed", None)
    baselines = read_csv(data / "baseline_per_binary_means.csv")
    operation_log = []

    apply_adjustments(records, adjustments, args.seed, operation_log)

    growth_summary = []
    if args.estimate_full:
        admin_summary = estimate_missing_admin(records, baselines, args.full_jitter, args.seed,
                                               args.growth_method, operation_log)
        growth_summary.append(admin_summary)
        caller_factor, overlap, caller_ratios = measured_nonadmin_admin_ratio(records)
        non_summary = estimate_missing_nonadmin_from_admin(
            records, baselines, args.full_jitter, args.seed, caller_factor, overlap,
            admin_summary["growth_factor"], operation_log)
        non_summary["observed_ratio_min"] = min(caller_ratios)
        non_summary["observed_ratio_max"] = max(caller_ratios)
        growth_summary.append(non_summary)

    write_json(records_path, records)
    align_progress_csv(data / "coverage_progress.csv", records, operation_log)
    align_time_csv(data / "coverage_time.csv", records, operation_log, 66.0)

    manifest = {
        "kind": "estimated-preview",
        "source_release": str(ROOT),
        "seed": args.seed,
        "growth_method": args.growth_method,
        "full_jitter": args.full_jitter,
        "adjustments": adjustments,
        "growth_summary": growth_summary,
        "operations": operation_log,
        "note": "Contains estimated/interpolated preview values; do not report them as completed experimental measurements.",
    }
    write_json(output / "PREVIEW_ESTIMATION.json", manifest)

    if not args.no_generate:
        generated = output / "generated"
        subprocess.run([sys.executable, str(output / "scripts" / "generate.py"), "--output", str(generated)],
                       cwd=output, check=True)
        src = generated / "figures"
        dst = output / "figures"
        if dst.exists():
            shutil.rmtree(dst)
        shutil.copytree(src, dst)

    print("\nPreview release:", output)
    for s in growth_summary:
        if s["caller"] == "admin":
            print(f"  admin vs MSFuzzer: factor={s['growth_factor']:.4f} "
