    # Rates/percentages: exact value when exact row has it; otherwise reference donor value
    # with tiny bounded perturbation, clamped to observed caller/profile range.
    for field in ('complete_sequences_per_minute','sequence_completion_percent','observed_filter_percent'):
        if exact_row is not None and numeric(exact_row.get(field)):
