import numpy as np, pandas as pd, math, itertools, statistics, os
df=pd.read_csv('/mnt/data/fleiss_kappa_realistic_data_adjusted_v2.csv')
groups=['Professional','Intermediate','Basic']
questions=df.Question.unique().tolist()
def mat_hist(mat):
    H=np.zeros((10,10),int)
    for i,row in enumerate(mat):
        for v in row: H[i,int(v)-1]+=1
    return H
def mats_for(q):
    out={}
    for g in groups:
        cols=['Rater_1','Rater_2','Rater_3'] if g!='Basic' else ['Rater_1','Rater_2','Rater_3','Rater_4']
        out[g]=df[(df.Group==g)&(df.Question==q)].sort_values('Task')[cols].astype(int).to_numpy()
    return out
def kappa_from_hists(P,I,B,pi=None,pb=None):
    if pi is None: pi=np.arange(10)
    if pb is None: pb=np.arange(10)
    C=P+I[pi]+B[pb]
    nr=10
    P_i=(np.sum(C*C,axis=1)-nr)/(nr*(nr-1))
    Pbar=P_i.mean()
    pj=C.sum(axis=0)/(10*nr)
    Pe=np.sum(pj*pj)
    return (Pbar-Pe)/(1-Pe)
def hill(q,restarts=100,steps=1000,seed=0):
    rng=np.random.default_rng(seed)
    mats=mats_for(q); P=mat_hist(mats['Professional']); I=mat_hist(mats['Intermediate']); B=mat_hist(mats['Basic'])
    best=(-1,None,None)
    for rr in range(restarts):
        pi=rng.permutation(10); pb=rng.permutation(10)
        cur=kappa_from_hists(P,I,B,pi,pb)
        improved=True
        for st in range(steps):
            # random best-ish swap among sampled
            which=rng.integers(2)
            perm=pi if which==0 else pb
            a,b=rng.choice(10,2,replace=False)
            perm[a],perm[b]=perm[b],perm[a]
            nv=kappa_from_hists(P,I,B,pi,pb)
            if nv>=cur:
                cur=nv
            else:
                perm[a],perm[b]=perm[b],perm[a]
            if cur>best[0]: best=(cur,pi.copy(),pb.copy())
    return best
for qi,q in enumerate(questions):
    b=hill(q,restarts=40,steps=400,seed=qi)
    print(q,'current',kappa_from_hists(*[mat_hist(mats_for(q)[g]) for g in groups]),'perm best',b[0])

