def mat(q,g):
    rr=[r for r in rows if r['Question']==q and r['Group']==g]
    return np.array([[int(float(r[c])) for c in cols[g]] for r in rr],np.int64)

targets=np.array([
 [0.643,0.648,0.646],
 [0.646,0.641,0.649],
 [0.639,0.647,0.645],
 [0.566,0.582,0.575],
 [0.648,0.638,0.646],
],dtype=np.float64)
ctarget=np.array([0.685,0.705,0.695,0.645,0.690],dtype=np.float64)

@njit
def kappa_block(X,start,end):
    n=10; m=end-start
    counts=np.zeros((10,10),np.int64)
    cats=np.zeros(10,np.int64)
    for i in range(n):
        for j in range(start,end):
            v=X[i,j]-1; counts[i,v]+=1; cats[v]+=1
    ps=0.0
    for i in range(n):
        ss=0
        for c in range(10): ss += counts[i,c]*counts[i,c]
        ps += (ss-m)/(m*(m-1))
    pbar=ps/n
    pe=0.0
    denom=n*m
    for c in range(10):
        pj=cats[c]/denom; pe += pj*pj
    if pe>=0.999999999: return 1.0
    return (pbar-pe)/(1-pe)

@njit
def block_stats(X,start,end):
    ident=0; maxpair=0; maxrange=0
    for i in range(10):
        same=True; mn=99; mx=-1
        first=X[i,start]
        for j in range(start,end):
            v=X[i,j]
            if v!=first: same=False
            if v<mn: mn=v
            if v>mx: mx=v
        if same: ident+=1
        if mx-mn>maxrange: maxrange=mx-mn
    for a in range(start,end):
        for b in range(start,a):
            c=0
            for i in range(10):
                if X[i,a]==X[i,b]: c+=1
            if c>maxpair: maxpair=c
