    return c

@njit
def objective(X, qi, tgts, ctargets):
    starts=(0,3,6); ends=(3,6,10)
    s=0.0
    kappas=np.empty(3,np.float64)
    for gi in range(3):
        k=kappa_block(X,starts[gi],ends[gi]); kappas[gi]=k
        tgt=tgts[qi,gi]
        if k<0.56: s += 100000*(0.56-k)*(0.56-k)+1000*(0.56-k)
        if k>0.65: s += 100000*(k-0.65)*(k-0.65)+1000*(k-0.65)
        s += 1800*(k-tgt)*(k-tgt)
        ident,mp,mx=block_stats(X,starts[gi],ends[gi])
        if ident<4: s += 120*(4-ident)*(4-ident)
        if ident>8: s += 120*(ident-8)*(ident-8)
        s += 1.0*(ident-6)*(ident-6)
        if mp>8: s += 180*(mp-8)*(mp-8)
        if mp==8: s += 0.5
        if mx<3: s += 80*(3-mx)*(3-mx)
        if mx>6: s += 80*(mx-6)*(mx-6)
    ck=kappa_block(X,0,10)
    ct=ctargets[qi]
    if ck<ct: s += 3800*(ct-ck)*(ct-ck)+40*(ct-ck)
    else: s += 350*(ck-ct)*(ck-ct)-2*(ck-ct)
    if ck>0.73: s += 10000*(ck-0.73)*(ck-0.73)
    i10=combined_ident(X)
    if i10<4: s += 80*(4-i10)*(4-i10)
    if i10>7: s += 120*(i10-7)*(i10-7)
    s += 0.8*(i10-5.5)*(i10-5.5)
