@njit
def anneal(X0,qi,tgts,ctargets,seed,iters):
    np.random.seed(seed)
    X=X0.copy(); cur=objective(X,qi,tgts,ctargets)
    bestX=X.copy(); best=cur
    T=5.0
    starts=np.array([0,3,6],np.int64); ends=np.array([3,6,10],np.int64)
    for it in range(iters):
        gi=np.random.randint(0,3); st=starts[gi]; en=ends[gi]
