        m=en-st; a=np.random.randint(0,10*m); b=np.random.randint(0,10*m-1)
        if b>=a:b+=1
        ia=a//m; ja=st+a%m; ib=b//m; jb=st+b%m
        step=1 if np.random.random()<0.5 else -1
        va=X[ia,ja]+step; vb=X[ib,jb]-step
        if va<1 or va>10 or vb<1 or vb>10: continue
        oa=X[ia,ja]; ob=X[ib,jb]; X[ia,ja]=va;X[ib,jb]=vb
        nxt=objective(X,qi,tgts,ctargets)
        if nxt<cur or np.random.random()<math.exp((cur-nxt)/max(T,1e-9)):
            cur=nxt
            if cur<best:
                best=cur;bestX=X.copy()
        else:
            X[ia,ja]=oa;X[ib,jb]=ob
        T*=0.999995
        if (it+1)%400000==0 and T<0.7: T=0.7
    return best,bestX

def metrics_py(X):
    def k(M):
        n,m=M.shape; counts=np.zeros((n,10),int)
