            for v in M[i]:counts[i,v-1]+=1
        P=((counts**2).sum(1)-m)/(m*(m-1)); pj=counts.sum(0)/(n*m);pe=(pj**2).sum();return float((P.mean()-pe)/(1-pe))
    out={}; starts=[0,3,6];ends=[3,6,10]
    for g,st,en in zip(groups,starts,ends):
        M=X[:,st:en];ident=sum(len(set(row))==1 for row in M);mp=max(sum(M[:,a]==M[:,b]) for a in range(M.shape[1]) for b in range(a));mx=max(row.max()-row.min() for row in M)
        out[g]=(k(M),ident,mp,int(mx),float(M.mean()),int(M.sum()))
    out['combined']=(k(X),sum(len(set(row))==1 for row in X))
    return out

