import pandas as pd, numpy as np, itertools, collections, math, random, json, time
SRC='/mnt/data/fleiss_kappa_realistic_data_adjusted_v3.csv'
df=pd.read_csv(SRC)
questions=['Q1 (Desc)','Q2 (Proto)','Q3 (Param)','Q4 (Ret)','Q5 (Struct)']
groups=['Professional','Intermediate','Basic']
rcols={'Professional':['Rater_1','Rater_2','Rater_3'], 'Intermediate':['Rater_1','Rater_2','Rater_3'], 'Basic':['Rater_1','Rater_2','Rater_3','Rater_4']}
targets={
'Q1 (Desc)': {'Professional':.638,'Intermediate':.636,'Basic':.633,'same':5,'comb_min':.55},
'Q2 (Proto)': {'Professional':.596,'Intermediate':.603,'Basic':.590,'same':4,'comb_min':.50},
'Q3 (Param)': {'Professional':.622,'Intermediate':.624,'Basic':.616,'same':5,'comb_min':.53},
'Q4 (Ret)': {'Professional':.560,'Intermediate':.570,'Basic':.565,'same':3,'comb_min':.48},
'Q5 (Struct)': {'Professional':.650,'Intermediate':.648,'Basic':.645,'same':5,'comb_min':.56},
}

def mat_for(q,g):
    sub=df[(df.Question==q)&(df.Group==g)].copy()
    sub['tn']=sub.Task.str.extract(r'(\d+)').astype(int)
    sub=sub.sort_values('tn')
    return sub[rcols[g]].astype(int).to_numpy()

def fk(M):
    n_items,nr=M.shape
    counts=np.zeros((n_items,10),dtype=np.int16)
    for i in range(n_items):
        counts[i]=np.bincount(M[i]-1,minlength=10)
    Pi=(np.sum(counts*counts,axis=1)-nr)/(nr*(nr-1))
    pj=counts.sum(axis=0)/(n_items*nr)
    pe=np.dot(pj,pj)
    return float((Pi.mean()-pe)/(1-pe)) if pe<1 else 1.0

def mode_unique(row):
    bc=np.bincount(row,minlength=11)[1:]
    mx=bc.max(); inds=np.flatnonzero(bc==mx)
    return int(inds[0]+1) if len(inds)==1 else -1

def same_modes(mats):
    c=0
    for i in range(10):
        ms=[mode_unique(mats[g][i]) for g in groups]
        if ms[0]>0 and ms[0]==ms[1]==ms[2]: c+=1
    return c

def unanim(M):
    return sum(np.all(r==r[0]) for r in M)

def maxpair(M):
    return max(int(np.sum(M[:,a]==M[:,b])) for a,b in itertools.combinations(range(M.shape[1]),2))

def longtail(M):
    return max(int(np.max(r)-np.min(r)) for r in M)

def combk(mats,gs): return fk(np.hstack([mats[g] for g in gs]))

def eval_score(mats,q):
    t=targets[q]; score=0.0; ks={}
    for g in groups:
        k=fk(mats[g]); ks[g]=k
        score += 4.0*((k-t[g])/0.008)**2
        if k<.555: score += 150*((.555-k)/.005)**2
        if k>.6545: score += 150*((k-.6545)/.005)**2
        u=unanim(mats[g])
        if u<4: score += 100*(4-u)**2
        if u>8: score += 100*(u-8)**2
        mp=maxpair(mats[g])
        if mp>8: score += 120*(mp-8)**2
        if longtail(mats[g])<3: score += 100
    sm=same_modes(mats)
    score += 8*((sm-t['same'])/1.2)**2
    ck=combk(mats,groups)
    if ck<t['comb_min']: score += 50*((t['comb_min']-ck)/.02)**2
    pairs=[]
    for a,b in itertools.combinations(groups,2):
        k=combk(mats,[a,b]); pairs.append(k)
        if k<.47: score += 50*((.47-k)/.02)**2
    # limit full 10-rater unanimous rows to avoid another obvious pattern
    allM=np.hstack([mats[g] for g in groups])
    fullu=sum(np.all(r==r[0]) for r in allM)
    if fullu>4: score += 8*(fullu-4)**2
    return score,ks,sm,ck,pairs,fullu

def anneal(q,seed,steps=35000):
    rng=np.random.default_rng(seed)
    mats={g:mat_for(q,g).copy() for g in groups}
    sums={g:int(mats[g].sum()) for g in groups}
    cur=eval_score(mats,q)
    best=(cur[0],{g:m.copy() for g,m in mats.items()},cur)
    T=3.0
    for it in range(steps):
        g=groups[int(rng.integers(3))]; M=mats[g]; size=M.size
        a=int(rng.integers(size)); b=int(rng.integers(size-1));
        if b>=a: b+=1
        i1,j1=divmod(a,M.shape[1]); i2,j2=divmod(b,M.shape[1])
        step=1 if rng.random()<.5 else -1
        if M[i1,j1]+step<1 or M[i1,j1]+step>10 or M[i2,j2]-step<1 or M[i2,j2]-step>10: continue
        v1,v2=M[i1,j1],M[i2,j2]; M[i1,j1]+=step; M[i2,j2]-=step
        nxt=eval_score(mats,q); d=nxt[0]-cur[0]
        if d<=0 or rng.random()<math.exp(-d/max(T,.03)):
            cur=nxt
            if cur[0]<best[0]: best=(cur[0],{gg:mm.copy() for gg,mm in mats.items()},cur)
        else:
            M[i1,j1],M[i2,j2]=v1,v2
        T=max(.05,T*.99991)
    assert all(int(best[1][g].sum())==sums[g] for g in groups)
    return best

results={}
for qi,q in enumerate(questions):
    BG=None
    for rr in range(3):
        b=anneal(q,10000+qi*100+rr,35000)
        if BG is None or b[0]<BG[0]: BG=b
    results[q]=BG
    print(q,'score',round(BG[0],3),'stats',BG[2],flush=True)

# save matrices to npz/json-friendly
out={}
for q,b in results.items():
    out[q]={g:b[1][g].tolist() for g in groups}
with open('/mnt/data/kappa_v4_mats.json','w') as f: json.dump(out,f,indent=2)
