rng=np.random.default_rng(12345)
def de_template_raters(M, trials=12000):
    nr,nc=M.shape
    base=M.copy()
    best=None
    overall=M.mean()
    for _ in range(trials):
        X=base.copy()
        for i in range(nr):
            if len(set(X[i]))>1:
                X[i]=rng.permutation(X[i])
        pair=[]
        for a in range(nc):
            for b in range(a+1,nc):
                pair.append(int(np.sum(X[:,a]==X[:,b])))
        pair=np.array(pair)
        colmeans=X.mean(axis=0)
        # column correlations; avoid exact profile copies
        corrs=[]
        for a in range(nc):
            for b in range(a+1,nc):
                if np.std(X[:,a])>0 and np.std(X[:,b])>0:
                    corrs.append(abs(np.corrcoef(X[:,a],X[:,b])[0,1]))
        maxcorr=max(corrs) if corrs else 0
        # prioritize max pair and balance, but don't over-engineer correlations
        score=100*pair.max()+2*np.var(pair)+0.5*np.var(colmeans)+0.05*maxcorr
        if best is None or score<best[0]:
            best=(score,X.copy(),pair,colmeans,maxcorr)
    return best

