p='/mnt/data/fleiss_kappa_realistic_data_adjusted_v5.csv'
df0=pd.read_csv(p)
questions=list(df0.Question.unique()); groups=list(df0.Group.unique())
rater_cols={'Professional':['Rater_1','Rater_2','Rater_3'],'Intermediate':['Rater_1','Rater_2','Rater_3'],'Basic':['Rater_1','Rater_2','Rater_3','Rater_4']}
EYE=np.eye(10,dtype=np.int8)

def task_sort(sub):
    return sub.sort_values('Task', key=lambda s:s.str.extract(r'(\d+)')[0].astype(int))
def get_mat(g,q):
    return task_sort(df0[(df0.Group==g)&(df0.Question==q)])[rater_cols[g]].astype(int).values.copy()
def fleiss(m):
    m=np.asarray(m,int); nr=m.shape[1]
    counts=EYE[m-1].sum(axis=1)
    Pi=(np.sum(counts*counts,axis=1)-nr)/(nr*(nr-1))
    pp=counts.sum(axis=0)/(m.size)
    pe=float(np.sum(pp*pp))
    return float((Pi.mean()-pe)/(1-pe)) if pe<1 else 1.0
def ident(m): return int(np.sum(np.all(m==m[:,[0]],axis=1)))
def maxpair(m):
    eq=m[:,:,None]==m[:,None,:]
    nr=m.shape[1]; mx=0
    for i in range(nr):
      for j in range(i): mx=max(mx,int(eq[:,i,j].sum()))
    return mx
def modev(row):
    bc=np.bincount(row,minlength=11); mx=bc.max(); inds=np.where(bc==mx)[0]; return int(inds[len(inds)//2])
def comb(mats): return fleiss(np.hstack(mats))
def pair(a,b): return fleiss(np.hstack([a,b]))

target_k={
'Professional':{'Q1 (Desc)':.63,'Q2 (Proto)':.59,'Q3 (Param)':.61,'Q4 (Ret)':.56,'Q5 (Struct)':.65},
'Intermediate':{'Q1 (Desc)':.61,'Q2 (Proto)':.62,'Q3 (Param)':.59,'Q4 (Ret)':.58,'Q5 (Struct)':.64},
'Basic':{'Q1 (Desc)':.60,'Q2 (Proto)':.58,'Q3 (Param)':.63,'Q4 (Ret)':.57,'Q5 (Struct)':.62}}
target_ident={
'Professional':{'Q1 (Desc)':6,'Q2 (Proto)':5,'Q3 (Param)':6,'Q4 (Ret)':4,'Q5 (Struct)':7},
'Intermediate':{'Q1 (Desc)':5,'Q2 (Proto)':6,'Q3 (Param)':5,'Q4 (Ret)':4,'Q5 (Struct)':7},
'Basic':{'Q1 (Desc)':6,'Q2 (Proto)':5,'Q3 (Param)':6,'Q4 (Ret)':5,'Q5 (Struct)':7}}
target_comb={'Q1 (Desc)':.59,'Q2 (Proto)':.55,'Q3 (Param)':.57,'Q4 (Ret)':.50,'Q5 (Struct)':.61}

def score(mats,q):
    s=0.0
    for g,m in zip(groups,mats):
        low=int(np.sum(m<5)); s+=3000*low
        excess=np.maximum(np.ptp(m,axis=1)-4,0); s+=5000*float(np.sum(excess*excess))
        k=fleiss(m); t=target_k[g][q]; s+=18000*(k-t)**2
        if k<.56: s+=200000*(.56-k)**2+1000
        if k>.65: s+=200000*(k-.65)**2+1000
        ic=ident(m); ti=target_ident[g][q]; s+=4*(ic-ti)**2
        pm=maxpair(m); s+=100*max(0,pm-8)**2
    ck=comb(mats); s+=6000*(ck-target_comb[q])**2 + 10000*max(0,.47-ck)**2
    for a,b in ((0,1),(0,2),(1,2)):
        pk=pair(mats[a],mats[b]); s+=5000*max(0,.47-pk)**2
    same=0
    for i in range(10):
        mm=[modev(m[i]) for m in mats]
        same += int(mm[0]==mm[1]==mm[2])
    s+=12*max(0,same-5)**2
    return s

def anneal(q,seed,iters=70000):
    rng=np.random.default_rng(seed); mats=[get_mat(g,q) for g in groups]
    cur=score(mats,q); best=(cur,[m.copy() for m in mats]); T=60.
    for it in range(iters):
        gi=int(rng.integers(3)); m=mats[gi]; nr=m.shape[1]
        r1=int(rng.integers(10)); c1=int(rng.integers(nr)); r2=int(rng.integers(10)); c2=int(rng.integers(nr))
        if r1==r2 and c1==c2: continue
        dr=1 if rng.random()<.5 else -1
        a=m[r1,c1]+dr; b=m[r2,c2]-dr
        if a<1 or a>10 or b<1 or b>10: continue
        o1,o2=m[r1,c1],m[r2,c2]; m[r1,c1]=a; m[r2,c2]=b
        nxt=score(mats,q); d=nxt-cur
        if d<=0 or rng.random()<math.exp(-d/max(T,.01)):
            cur=nxt
            if cur<best[0]: best=(cur,[x.copy() for x in mats])
        else: m[r1,c1]=o1; m[r2,c2]=o2
        T=max(.03,T*.99992)
    return best

