print('combined',comb(best[1]),'pairs',[pair(best[1][a],best[1][b]) for a,b in ((0,1),(0,2),(1,2))], 'same_modes',sum(modev(best[1][0][i])==modev(best[1][1][i])==modev(best[1][2][i]) for i in range(10)))
