df=pd.read_csv('/mnt/data/fleiss_kappa_realistic_data_adjusted_v5.csv')
groups=['Professional','Intermediate','Basic']
questions=list(df.Question.unique())
cols={'Professional':['Rater_1','Rater_2','Rater_3'],'Intermediate':['Rater_1','Rater_2','Rater_3'],'Basic':['Rater_1','Rater_2','Rater_3','Rater_4']}
E=np.eye(10,dtype=np.int8)

def sortsub(g,q):
    return df[(df.Group==g)&(df.Question==q)].sort_values('Task',key=lambda s:s.str.extract(r'(\d+)')[0].astype(int))
def fleiss(m):
    m=np.asarray(m,int); nr=m.shape[1]
    cnt=E[m-1].sum(axis=1)
    P=(np.sum(cnt*cnt,axis=1)-nr)/(nr*(nr-1))
    p=cnt.sum(axis=0)/m.size; pe=float(np.sum(p*p))
    return float((P.mean()-pe)/(1-pe))
def ident(m):return int(np.sum(np.all(m==m[:,[0]],axis=1)))
def maxpair(m):
    return max(int(np.sum(m[:,a]==m[:,b])) for a,b in itertools.combinations(range(m.shape[1]),2))
def repair(m,minv=5):
    m=m.copy()
    for i in range(len(m)):
        for _ in range(30):
            lo=int(np.argmin(m[i])); hi=int(np.argmax(m[i]))
            if m[i,hi]-m[i,lo] <=4: break
            m[i,lo]+=1; m[i,hi]-=1
    for _ in range(200):
        bad=np.argwhere(m<minv)
        if not len(bad):break
        i,j=bad[0]
        cand=[]
        for a in range(m.shape[0]):
            for b in range(m.shape[1]):
                if m[a,b]<=minv: continue
                old=m[a,b];m[a,b]-=1;ok=np.ptp(m[a])<=4;m[a,b]=old
                if ok:cand.append((old,a,b))
        if not cand:break
        _,a,b=max(cand);m[i,j]+=1;m[a,b]-=1
    return m

kt={
'Professional':[.61,.59,.60,.56,.64],
'Intermediate':[.63,.61,.59,.58,.65],
'Basic':[.58,.60,.63,.57,.62]}
itgt={
'Professional':[5,6,5,4,7],
'Intermediate':[7,5,6,4,7],
'Basic':[5,6,5,4,7]}

def obj(m,t,ic):
    k=fleiss(m)
    s=12000*(k-t)**2+8*(ident(m)-ic)**2
    if k<.56:s+=50000*(.56-k)**2+100
    if k>.65:s+=50000*(k-.65)**2+100
    mp=maxpair(m)
    if mp>8:s+=20*(mp-8)**2
    # discourage many identical numerical rows
    pats=Counter(tuple(r) for r in m)
    s+=.4*sum(max(0,v-2)**2 for v in pats.values())
    return s

def opt_matrix(m,t,ic,seed,iters=12000):
    rng=np.random.default_rng(seed)
    m=repair(m)
    cur=obj(m,t,ic);best=(cur,m.copy())
    T=3.0
    for it in range(iters):
        nr=m.shape[1]
        a=int(rng.integers(10)); b=int(rng.integers(nr))
        c=int(rng.integers(10)); d=int(rng.integers(nr))
        if a==c and b==d:continue
        sign=1 if rng.random()<.5 else -1
        x=m[a,b]+sign;y=m[c,d]-sign
        if x<5 or x>10 or y<5 or y>10:continue
        o1,o2=m[a,b],m[c,d]
        m[a,b],m[c,d]=x,y
        if np.ptp(m[a])>4 or np.ptp(m[c])>4:
            m[a,b],m[c,d]=o1,o2;continue
        nv=obj(m,t,ic);dd=nv-cur
        if dd<=0 or rng.random()<math.exp(-dd/max(T,.02)):
            cur=nv
            if cur<best[0]:best=(cur,m.copy())
        else:m[a,b],m[c,d]=o1,o2
        T=max(.02,T*.9996)
    return best[1]

res={}
t0=time.time()
for g in groups:
    for qi,q in enumerate(questions):
        m=sortsub(g,q)[cols[g]].astype(int).values
        best=None
        for rep in range(2):
            mm=opt_matrix(m,kt[g][qi],itgt[g][qi],1000+qi*10+rep+100*groups.index(g))
            sc=obj(mm,kt[g][qi],itgt[g][qi])
            if best is None or sc<best[0]:best=(sc,mm)
        res[(g,q)]=best[1]
        mm=best[1]
        print(g,q,'sum',mm.sum(),'k',round(fleiss(mm),4),'ident',ident(mm),'min',mm.min(),'range',np.ptp(mm,axis=1).max(),'pair',maxpair(mm))
print('time',time.time()-t0)

