import numpy as np,itertools
# res persists in same python session? Yes python tool stateful perhaps from previous call.
def pairk(a,b):return fleiss(np.hstack([a,b]))
def combk(ms):return fleiss(np.hstack(ms))
ks={g:[] for g in groups}
print('Combined:')
combvals={}
for q in questions:
    ms=[res[(g,q)] for g in groups]
    cv=combk(ms);combvals[q]=cv
    print(q,cv,'pairs',[pairk(ms[a],ms[b]) for a,b in [(0,1),(0,2),(1,2)]],
          'same modes',sum((lambda vals: len(set(vals))==1)([Counter(m[i]).most_common(1)[0][0] for m in ms]) for i in range(10)))
    for g,m in zip(groups,ms):ks[g].append(fleiss(m))
print('corrs')
for a,b in itertools.combinations(groups,2):print(a,b,np.corrcoef(ks[a],ks[b])[0,1],ks[a],ks[b])
print('overall order',sorted(combvals.items(),key=lambda x:x[1],reverse=True))

