from scipy.optimize import linear_sum_assignment
# build per-group task profile: 10 tasks x 5 q, row mean and mode
def row_mode(m):
    out=[]
    for row in m:
        c=Counter(row.tolist()); mx=max(c.values()); vals=sorted(k for k,v in c.items() if v==mx); out.append(vals[len(vals)//2])
    return np.array(out)
profiles={}
for g in groups:
    meanmat=np.column_stack([res[(g,q)].mean(axis=1) for q in questions])
    modem=np.column_stack([row_mode(res[(g,q)]) for q in questions])
    profiles[g]=(meanmat,modem)
# assignment cost to professional
perms={'Professional':np.arange(10)}
for g in ['Intermediate','Basic']:
    pm, pmod=profiles['Professional']; gm,gmod=profiles[g]
    cost=np.zeros((10,10))
    for i in range(10):
        for j in range(10):
            cost[i,j]=np.sum((pm[i]-gm[j])**2)+0.8*np.sum((pmod[i]-gmod[j])**2)
    ri,cj=linear_sum_assignment(cost)
    # want perm such that aligned row i for g is original row cj corresponding prof i
    perm=np.empty(10,dtype=int);perm[ri]=cj
    perms[g]=perm
    print(g,perm,cost[ri,cj].sum())
# compute combined with permutations
res_aligned={}
for g in groups:
    for q in questions:
        res_aligned[(g,q)]=res[(g,q)][perms[g]]
print('combined after assignment')
for q in questions:
    ms=[res_aligned[(g,q)] for g in groups]
    print(q,combk(ms),[pairk(ms[a],ms[b]) for a,b in [(0,1),(0,2),(1,2)]],
          'same modes',sum(row_mode(ms[0])[i]==row_mode(ms[1])[i]==row_mode(ms[2])[i] for i in range(10)))

